from AlgorithmImports import *
from collections import deque
import math


class FixedStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.subscribed_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_closes = deque(maxlen=201)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_buy_pending = False
        self.strategy_a_sell_pending = False
        self.strategy_b_buy_pending = False
        self.strategy_b_sell_pending = False

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.subscribed_symbols):
            return

        strategy_a_was_nonempty = self.strategy_a_lot > 0
        strategy_b_was_nonempty = self.strategy_b_lot > 0

        # Evaluate all sells before any buys.
        if (
            strategy_a_was_nonempty
            and not self.strategy_a_sell_pending
            and self._strategy_a_sell_reason()
        ):
            self._sell_strategy_a_lot()

        if (
            strategy_b_was_nonempty
            and not self.strategy_b_sell_pending
            and self._strategy_b_sell_reason()
        ):
            self._sell_strategy_b_lot()

        # Evaluate buys only for lots that were empty at the start of the bar.
        if (
            not strategy_a_was_nonempty
            and self.strategy_a_lot == 0
            and not self.strategy_a_buy_pending
            and self._strategy_a_buy_reason()
        ):
            self._buy_strategy_a_lot()

        if (
            not strategy_b_was_nonempty
            and self.strategy_b_lot == 0
            and not self.strategy_b_buy_pending
            and self._strategy_b_buy_reason()
        ):
            self._buy_strategy_b_lot()

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            current_close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if current_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = current_close

    def _crosses_above_sma(self, closes, period):
        if len(closes) < period + 1:
            return False

        values = list(closes)
        yesterday_close = values[-2]
        today_close = values[-1]

        yesterday_sma = sum(values[-period - 1:-1]) / period
        today_sma = sum(values[-period:]) / period

        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _crosses_below_sma(self, closes, period):
        if len(closes) < period + 1:
            return False

        values = list(closes)
        yesterday_close = values[-2]
        today_close = values[-1]

        yesterday_sma = sum(values[-period - 1:-1]) / period
        today_sma = sum(values[-period:]) / period

        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _strategy_a_buy_reason(self):
        return self._crosses_above_sma(self.spy_closes, 200)

    def _strategy_a_sell_reason(self):
        return self._crosses_below_sma(self.spy_closes, 50)

    def _strategy_b_buy_reason(self):
        return self.aapl_red_streak >= 3

    def _strategy_b_sell_reason(self):
        return self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60

    def _buy_strategy_a_lot(self):
        close = float(self.Securities[self.spy].Price)
        if close <= 0:
            return

        target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
        quantity = int(math.floor(target_value / close))

        if quantity <= 0:
            return

        self.strategy_a_buy_pending = True
        ticket = self.MarketOrder(
            self.spy,
            quantity,
            tag="Strategy A Buy"
        )

        if ticket is None:
            self.strategy_a_buy_pending = False

    def _sell_strategy_a_lot(self):
        if self.strategy_a_lot <= 0:
            return

        self.strategy_a_sell_pending = True
        ticket = self.MarketOrder(
            self.spy,
            -self.strategy_a_lot,
            tag="Strategy A Sell"
        )

        if ticket is None:
            self.strategy_a_sell_pending = False

    def _buy_strategy_b_lot(self):
        close = float(self.Securities[self.aapl].Price)
        if close <= 0 or float(self.Portfolio.Cash) < 20000.0:
            return

        quantity = int(math.floor(20000.0 / close))
        if quantity <= 0:
            return

        self.strategy_b_buy_pending = True
        ticket = self.MarketOrder(
            self.aapl,
            quantity,
            tag="Strategy B Buy"
        )

        if ticket is None:
            self.strategy_b_buy_pending = False

    def _sell_strategy_b_lot(self):
        if self.strategy_b_lot <= 0:
            return

        self.strategy_b_sell_pending = True
        ticket = self.MarketOrder(
            self.aapl,
            -self.strategy_b_lot,
            tag="Strategy B Sell"
        )

        if ticket is None:
            self.strategy_b_sell_pending = False

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        fill_quantity = int(order_event.FillQuantity)

        if order.Tag == "Strategy A Buy":
            self.strategy_a_lot += fill_quantity
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_buy_pending = False

        elif order.Tag == "Strategy A Sell":
            self.strategy_a_lot = max(0, self.strategy_a_lot + fill_quantity)
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_sell_pending = False

        elif order.Tag == "Strategy B Buy":
            self.strategy_b_lot += fill_quantity
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_buy_pending = False

        elif order.Tag == "Strategy B Sell":
            self.strategy_b_lot = max(0, self.strategy_b_lot + fill_quantity)
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_sell_pending = False
