import math


class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.subscribed_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(200, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.current_spy_sma_200 = None
        self.current_spy_sma_50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_buy_pending = False
        self.strategy_a_sell_pending = False
        self.strategy_b_buy_pending = False
        self.strategy_b_sell_pending = False

        self.pending_orders = {}

    def OnData(self, data: Slice):
        bars = {}
        all_bars_present = True

        for symbol in self.subscribed_symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]
            else:
                all_bars_present = False

        if self.spy in bars:
            self._update_spy_state(float(bars[self.spy].Close))

        if self.aapl in bars:
            self._update_aapl_state(float(bars[self.aapl].Close))

        if self.IsWarmingUp or not all_bars_present:
            return

        if not (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and self.current_spy_sma_200 is not None
            and self.current_spy_sma_50 is not None
            and self.previous_aapl_close is not None
        ):
            return

        spy_close_crosses_above_sma_200 = (
            self.previous_spy_close <= self.previous_spy_sma_200
            and self.previous_spy_close is not None
            and self.spy_close > self.current_spy_sma_200
        )

        spy_close_crosses_below_sma_50 = (
            self.previous_spy_close >= self.previous_spy_sma_50
            and self.spy_close < self.current_spy_sma_50
        )

        aapl_rsi_above_60 = self.aapl_rsi_14.Current.Value > 60
        aapl_red_for_three_days = self.aapl_red_streak >= 3

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_sell_pending
            and spy_close_crosses_below_sma_50
        ):
            self._submit_order(
                self.spy,
                -self.strategy_a_lot,
                "A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_sell_pending
            and aapl_rsi_above_60
        ):
            self._submit_order(
                self.aapl,
                -self.strategy_b_lot,
                "B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_buy_pending
            and not self.strategy_a_sell_pending
            and spy_close_crosses_above_sma_200
        ):
            quantity = int(math.floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue)
                / self.spy_close
            ))

            if quantity > 0:
                self._submit_order(self.spy, quantity, "A_BUY")

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_buy_pending
            and not self.strategy_b_sell_pending
            and aapl_red_for_three_days
            and float(self.Portfolio.Cash) >= 20000
        ):
            quantity = int(math.floor(20000 / self.aapl_close))

            if quantity > 0:
                self._submit_order(self.aapl, quantity, "B_BUY")

    def _update_spy_state(self, close):
        self.spy_close = close

        if self.spy_sma_200.IsReady:
            self.previous_spy_sma_200 = self.current_spy_sma_200
            self.current_spy_sma_200 = float(self.spy_sma_200.Current.Value)

        if self.spy_sma_50.IsReady:
            self.previous_spy_sma_50 = self.current_spy_sma_50
            self.current_spy_sma_50 = float(self.spy_sma_50.Current.Value)

        self.previous_spy_close = close if self.previous_spy_close is None else self.spy_close_previous
        self.spy_close_previous = close

    def _update_aapl_state(self, close):
        self.aapl_close = close

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.previous_aapl_close = close

    def _submit_order(self, symbol, quantity, order_type):
        ticket = self.MarketOrder(symbol, quantity, tag=order_type)

        filled_quantity = int(ticket.QuantityFilled)
        if filled_quantity != 0:
            self._apply_fill(order_type, filled_quantity)

        if ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[ticket.OrderId] = order_type
            self._set_pending(order_type, True)

    def OnOrderEvent(self, order_event):
        order_type = self.pending_orders.get(order_event.OrderId)
        if order_type is None:
            return

        filled_quantity = int(order_event.FillQuantity)
        if filled_quantity != 0:
            self._apply_fill(order_type, filled_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders.pop(order_event.OrderId, None)
            self._set_pending(order_type, False)

    def _apply_fill(self, order_type, filled_quantity):
        if order_type == "A_BUY":
            self.strategy_a_lot += filled_quantity
        elif order_type == "A_SELL":
            self.strategy_a_lot = max(
                0,
                self.strategy_a_lot + filled_quantity
            )
        elif order_type == "B_BUY":
            self.strategy_b_lot += filled_quantity
        elif order_type == "B_SELL":
            self.strategy_b_lot = max(
                0,
                self.strategy_b_lot + filled_quantity
            )

    def _set_pending(self, order_type, pending):
        if order_type == "A_BUY":
            self.strategy_a_buy_pending = pending
        elif order_type == "A_SELL":
            self.strategy_a_sell_pending = pending
        elif order_type == "B_BUY":
            self.strategy_b_buy_pending = pending
        elif order_type == "B_SELL":
            self.strategy_b_sell_pending = pending
